import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

// Runnable driver for the pipelines shown in FarmersMarketApp. It carries a small
// stand-in product class and sample data so the sorted, distinct, and limit steps
// can be executed and their output compared.
public class FarmersMarketAppRunner {

    static class Product {
        private final String name;
        private final double price;
        private final boolean organic;
        private final String season;
        private final String vendor;

        Product(String name, double price, boolean organic, String season, String vendor) {
            this.name = name;
            this.price = price;
            this.organic = organic;
            this.season = season;
            this.vendor = vendor;
        }

        public String getName() { return name; }
        public double getPrice() { return price; }
        public boolean isOrganic() { return organic; }
        public String getSeason() { return season; }
        public String getVendor() { return vendor; }
    }

    public static void main(String[] args) {
        List<Product> products = new ArrayList<>();
        products.add(new Product("Heirloom Tomatoes", 4.50, true, "Summer", "Green Acres"));
        products.add(new Product("Sweet Corn", 3.25, true, "Summer", "Green Acres"));
        products.add(new Product("Sourdough Loaf", 6.00, false, "All", "Baker's Lane"));
        products.add(new Product("Blueberry Scone", 3.75, false, "Summer", "Baker's Lane"));
        products.add(new Product("Cinnamon Roll", 4.25, false, "All", "Baker's Lane"));
        products.add(new Product("Apple Turnover", 3.95, false, "Fall", "Baker's Lane"));
        products.add(new Product("Goat Cheese", 7.50, true, "Summer", "Hillside Dairy"));

        List<String> organicSummerNames = products.stream()
                .filter(p -> p.isOrganic() && p.getSeason() != null && p.getSeason().toLowerCase().contains("summer"))
                .sorted(Comparator.comparingDouble(Product::getPrice))
                .map(Product::getName)
                .collect(Collectors.toList());
        System.out.println("\nOrganic summer items by price: " + organicSummerNames);

        List<String> vendors = products.stream()
                .map(Product::getVendor)
                .filter(v -> v != null && !v.isBlank())
                .distinct()
                .sorted()
                .collect(Collectors.toList());
        System.out.println("\nVendors (sorted): " + vendors);

        String vendor = "Baker's Lane";
        List<String> menu = products.stream()
                .filter(p -> p.getVendor() != null && p.getVendor().equalsIgnoreCase(vendor))
                .map(p -> p.getName() + " - $" + String.format("%.2f", p.getPrice()))
                .limit(3)
                .collect(Collectors.toList());
        System.out.println("\n" + vendor + " menu:");
        menu.forEach(System.out::println);

        List<Double> discountedPrices = products.stream()
                .filter(p -> p.getVendor() != null && p.getVendor().equalsIgnoreCase(vendor))
                .map(p -> Math.round(p.getPrice() * 0.90 * 100) / 100.0)
                .collect(Collectors.toList());
        System.out.println("\nDiscounted prices for " + vendor + ": " + discountedPrices);
    }
}
